#include <stdio.h>
#include <time.h>

static double seconds(struct timespec t) {
    return t.tv_sec + t.tv_nsec / 1e9;
}

int main(void) {
    const clockid_t clocks[] = {CLOCK_MONOTONIC, CLOCK_MONOTONIC_COARSE, CLOCK_REALTIME, CLOCK_REALTIME_COARSE};
    const unsigned long iterations = 10000000;
    for (int round = 0; round < 3; round++) {
        for (int index = 0; index < 8; index++) {
            clockid_t id = clocks[((index / 2) + round) % 4];
            struct timespec start, finish, cpu_start, cpu_finish, value;
            clock_gettime(CLOCK_MONOTONIC, &start);
            clock_gettime(CLOCK_THREAD_CPUTIME_ID, &cpu_start);
            for (unsigned long n = 0; n < iterations; n++) {
                if (clock_gettime(id, &value) != 0) return 1;
            }
            clock_gettime(CLOCK_THREAD_CPUTIME_ID, &cpu_finish);
            clock_gettime(CLOCK_MONOTONIC, &finish);
            printf("%d,%d,%.3f,%.3f\n", round + 1, id,
                   (seconds(finish) - seconds(start)) * 1e9 / iterations,
                   (seconds(cpu_finish) - seconds(cpu_start)) * 1e9 / iterations);
        }
    }
}
